"""Ordered beginner-first lessons for every FelixForge Academy learning path.

Each entry is (title, teaching text, worked code/example).  The seeder matches
lessons by title so adding these lessons at the beginning does not change the
IDs of existing lessons or detach saved learner progress.
"""


def lesson(title, objective, explanation, example, mistakes, practice, next_step=''):
    body = f'''LEARNING OBJECTIVE\n{objective}\n\n{explanation}\n\nWORKED EXAMPLE\nRead the example from top to bottom. First identify the input or starting value, then follow each instruction in order. Pay attention to the names and punctuation used by this language.\n\nCOMMON BEGINNER MISTAKES\n{mistakes}\n\nPRACTICE\n{practice}'''
    if next_step:
        body += f'\n\nCHECK YOUR UNDERSTANDING\n{next_step}'
    return (title, body, example)


